actions.script:
$liteState = Join-Path $env:ProgramData 'LiteOS'
if (-not (Test-Path -LiteralPath $liteState)) { New-Item -ItemType Directory -Path $liteState -Force | Out-Null }
# per-user script: the engine sets $LiteOSUserRoot (HKCU: or the Default profile hive) and $LiteOSHiveTag
if (-not $LiteOSUserRoot) { $LiteOSUserRoot = 'HKCU:' }
if (-not $LiteOSHiveTag) { $LiteOSHiveTag = [System.Security.Principal.WindowsIdentity]::GetCurrent().User.Value }
$regPath = $LiteOSUserRoot + '\Software\Microsoft\DirectX\UserGpuPreferences'
$valueName = 'DirectXUserGlobalSettings'
$entry = 'SwapEffectUpgradeEnable'
$stateFile = Join-Path $liteState ('prev-dx-' + $entry + '-' + $LiteOSHiveTag + '.txt')
function Get-LiteDxPairs {
    $pairs = [ordered]@{}
    if (Test-Path -LiteralPath $regPath) {
        $current = [string](Get-Item -LiteralPath $regPath).GetValue($valueName, '')
        foreach ($part in $current.Split(';')) {
            $p = $part.Trim()
            $eq = $p.IndexOf('=')
            if ($eq -gt 0) { $pairs[$p.Substring(0, $eq)] = $p.Substring($eq + 1) }
        }
    }
    $pairs
}
function Set-LiteDxPairs {
    param($Pairs)
    if ($Pairs.Count -eq 0) {
        if ((Test-Path -LiteralPath $regPath) -and ($null -ne (Get-Item -LiteralPath $regPath).GetValue($valueName, $null))) {
            Remove-ItemProperty -LiteralPath $regPath -Name $valueName
        }
    } else {
        if (-not (Test-Path -LiteralPath $regPath)) { New-Item -Path $regPath -Force | Out-Null }
        $text = (@($Pairs.Keys | ForEach-Object { [string]$_ + '=' + [string]$Pairs[$_] }) -join ';') + ';'
        New-ItemProperty -LiteralPath $regPath -Name $valueName -PropertyType String -Value $text -Force | Out-Null
    }
}
$pairs = Get-LiteDxPairs
if ($pairs.Contains($entry) -and [string]$pairs[$entry] -eq '1') {
    Write-Output ('UNCHANGED: ' + $entry + '=1 is already set in ' + $valueName + '.')
} else {
    if (-not (Test-Path -LiteralPath $stateFile)) {
        $prev = '<absent>'
        if ($pairs.Contains($entry)) { $prev = [string]$pairs[$entry] }
        Set-Content -LiteralPath $stateFile -Value $prev -Encoding ASCII
    }
    $pairs[$entry] = '1'
    Set-LiteDxPairs -Pairs $pairs
    Write-Output ('LiteOS: ' + $entry + '=1 merged into ' + $valueName + '; other settings kept.')
}

