actions.script:
$liteState = Join-Path $env:ProgramData 'LiteOS'
if (-not (Test-Path -LiteralPath $liteState)) { New-Item -ItemType Directory -Path $liteState -Force | Out-Null }
# per-user script: the engine sets $LiteOSUserRoot (HKCU: or the Default profile hive) and $LiteOSHiveTag
if (-not $LiteOSUserRoot) { $LiteOSUserRoot = 'HKCU:' }
if (-not $LiteOSHiveTag) { $LiteOSHiveTag = [System.Security.Principal.WindowsIdentity]::GetCurrent().User.Value }
$accBase = $LiteOSUserRoot + '\Control Panel\Accessibility\'
$stateFile = Join-Path $liteState ('prev-accessibility-flags-' + $LiteOSHiveTag + '.txt')
$keyNames = @('StickyKeys', 'ToggleKeys', 'Keyboard Response')
$found = @()
$toChange = @()
foreach ($k in $keyNames) {
    $path = $accBase + $k
    if (Test-Path -LiteralPath $path) {
        $raw = (Get-Item -LiteralPath $path).GetValue('Flags', $null)
        $n = 0
        if ($null -ne $raw -and [int]::TryParse([string]$raw, [ref]$n)) {
            $found += ($k + '=' + [string]$raw)
            # bit 4 = the keyboard shortcut (Shift x5, hold Right Shift, hold Num Lock)
            if (($n -band 4) -ne 0) { $toChange += ($k + '=' + [string]$raw) }
        }
    }
}
if ($toChange.Count -eq 0) {
    Write-Output 'UNCHANGED: the Sticky/Filter/Toggle Keys shortcuts are already off.'
} else {
    if (-not (Test-Path -LiteralPath $stateFile)) {
        Set-Content -LiteralPath $stateFile -Value $found -Encoding ASCII
    }
    foreach ($line in $toChange) {
        $eq = $line.IndexOf('=')
        $k = $line.Substring(0, $eq)
        $n = [int]$line.Substring($eq + 1)
        $new = $n -band (-bnot 4)
        Set-ItemProperty -LiteralPath ($accBase + $k) -Name 'Flags' -Value ([string]$new) -Type String
    }
    Write-Output ('LiteOS: accessibility shortcut keys turned off for ' + $toChange.Count + ' feature(s); takes effect at next sign-in.')
}

actions.undo:
$liteState = Join-Path $env:ProgramData 'LiteOS'
if (-not $LiteOSUserRoot) { $LiteOSUserRoot = 'HKCU:' }
if (-not $LiteOSHiveTag) { $LiteOSHiveTag = [System.Security.Principal.WindowsIdentity]::GetCurrent().User.Value }
$accBase = $LiteOSUserRoot + '\Control Panel\Accessibility\'
$stateFile = Join-Path $liteState ('prev-accessibility-flags-' + $LiteOSHiveTag + '.txt')
# no state file = this revert already ran (or the tweak changed nothing): leave the flags alone
if (Test-Path -LiteralPath $stateFile) {
    foreach ($line in @(Get-Content -LiteralPath $stateFile)) {
        $s = [string]$line
        $eq = $s.IndexOf('=')
        $prev = 0
        if ($eq -gt 0 -and [int]::TryParse($s.Substring($eq + 1), [ref]$prev)) {
            $path = $accBase + $s.Substring(0, $eq)
            if (Test-Path -LiteralPath $path) {
                # put back only the shortcut bit (4); other flags may have been changed in Settings since
                $raw = (Get-Item -LiteralPath $path).GetValue('Flags', $null)
                $cur = 0
                if ($null -ne $raw -and [int]::TryParse([string]$raw, [ref]$cur)) {
                    $new = ($cur -band (-bnot 4)) -bor ($prev -band 4)
                } else {
                    $new = $prev
                }
                Set-ItemProperty -LiteralPath $path -Name 'Flags' -Value ([string]$new) -Type String
            }
        }
    }
    Remove-Item -LiteralPath $stateFile -Force
    Write-Output 'LiteOS: accessibility shortcut keys restored; takes effect at next sign-in.'
} else {
    Write-Output 'LiteOS: no saved accessibility shortcut state for this profile - nothing to revert.'
}
